mapper.select:
SELECT EXISTS(SELECT 1 FROM public.agent_runtime_dag_control_runs c
    JOIN public.agent_runtime_execution_runs r ON r.tenant_id=c.tenant_id AND r.run_id=c.run_id
    WHERE c.tenant_id=#{work.key.owner.sessionRef.tenantId.value}
        AND c.session_id=#{work.key.owner.sessionRef.sessionId} AND c.root_input_id=#{work.key.rootInputId.value}
        AND c.run_id=#{work.request.controlRun.runId} AND c.agent_id=#{work.coordinator.value}
        AND r.status NOT IN ('COMPLETED','FAILED','CANCELLED','TERMINATED') AND NOT r.cancelled)

SELECT EXISTS(SELECT 1 FROM public.agent_runtime_dag_inputs i
    JOIN public.agent_runtime_dag_control_runs c ON c.tenant_id=i.tenant_id AND c.session_id=i.session_id AND c.root_input_id=i.root_input_id
    JOIN public.agent_runtime_session_events e ON e.tenant_id=i.tenant_id AND e.session_id=i.session_id
        AND e.input_id=i.root_input_id AND e.caused_by_event_id='control:' || i.input_id
        AND e.event_type='work.cancel_requested' AND e.payload_schema_id='dag.work.v1'
    WHERE i.tenant_id=#{work.key.owner.sessionRef.tenantId.value} AND i.session_id=#{work.key.owner.sessionRef.sessionId}
        AND i.root_input_id=#{work.key.rootInputId.value} AND i.state='ACCEPTED'
        AND c.run_id=#{work.request.controlRun.runId} AND c.agent_id=#{work.coordinator.value}
        AND e.target_kind=#{work.key.owner.target.kind} AND e.target_id=#{work.key.owner.target.id}
        AND e.end_user_id IS NOT DISTINCT FROM NULL#{work.key.owner.requireUser.value})

SELECT a.binding FROM public.agent_runtime_dag_admissions a
JOIN public.agent_runtime_dag_works w USING(tenant_id,session_id,root_input_id)
JOIN public.agent_runtime_dag_control_runs c USING(tenant_id,session_id,root_input_id)
WHERE a.tenant_id=#{key.owner.sessionRef.tenantId.value} AND a.session_id=#{key.owner.sessionRef.sessionId}
    AND a.root_input_id=#{key.rootInputId.value} AND a.task_id=#{binding.task.id}
    AND a.admission_id=#{binding.admissionId} AND a.run_id=#{binding.runRef.runId}
    AND a.agent_id=#{binding.task.agentId.value} AND a.executor_type='MEMBER' AND a.plan_revision=#{binding.planRevision}
    AND w.target_kind=#{key.owner.target.kind} AND w.target_id=#{key.owner.target.id} AND w.end_user_id IS NOT DISTINCT FROM NULL#{key.owner.requireUser.value}
    AND c.run_id=#{parent.runRef.runId} AND c.agent_id=#{parent.agentId.value} AND c.role='WORKING'
FOR UPDATE OF a

SELECT fence FROM public.agent_runtime_dag_permits
WHERE tenant_id=#{binding.runRef.tenantId.value} AND run_id=#{binding.runRef.runId}
    AND admission_id=#{binding.admissionId} AND fence=#{permit.fence}
    AND expires_at=#{permit.expiresAt} AND expires_at>clock_timestamp()
FOR UPDATE
